const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const region = ee.Geometry.Rectangle([-180, -40, 180, 0]); // 0 to 40°S, global
    const date = '2025-02-26';

    // 2. Data Acquisition - Use visible imagery (MODIS) for cloud pattern detection
    const collection = ee.ImageCollection('MODIS/061/MYD09GA')
      .filterDate(date, ee.Date(date).advance(1, 'day'))
      .filterBounds(region)
      .select(['sur_refl_b01', 'sur_refl_b04', 'sur_refl_b03']); // RGB bands

    // Check for data availability
    const count = collection.size().getInfo();
    console.log(`Images on ${date}: ${count}`);

    if (count === 0) {
      console.log("<answer>C1</answer>");
      return;
    }

    // 3. Processing - Create cloud-free composite
    const composite = collection.median();

    // Count valid pixels
    const pixelCount = composite.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: region,
      scale: 1000,
      maxPixels: 1e9
    }).get('sur_refl_b01').getInfo();

    console.log(`Valid pixels: ${pixelCount}`);

    if (pixelCount === 0) {
      console.log("<answer>C2</answer>");
      return;
    }

    // 4. Tropical Cyclone Detection Logic
    // Simple approach: Look for circular cloud patterns using texture/edge detection
    const gray = composite.expression(
      '0.3*R + 0.59*G + 0.11*B',
      {'R': composite.select('sur_refl_b01'),
       'G': composite.select('sur_refl_b04'),
       'B': composite.select('sur_refl_b03')}
    );

    const edges = gray.edgeDetect();

    // Find circular features (tropical cyclones often have circular cloud patterns)
    const texture = edges.reduceNeighborhood({
      reducer: ee.Reducer.stdDev(),
      kernel: ee.Kernel.circle(10000), // 10km radius
      optimization: 'box'
    });

    // Threshold for cyclone-like features
    const cyclones = texture.gt(0.05).selfMask();

    // Count distinct blobs (potential cyclones)
    const objects = cyclones.connectedComponents({
      connectedness: ee.Kernel.plus(1),
      maxSize: 100
    });

    const uniqueCount = objects.select('labels')
      .reduceRegion({
        reducer: ee.Reducer.countDistinct(),
        geometry: region,
        scale: 50000, // 50km scale for counting distinct systems
        maxPixels: 1e9
      }).get('labels').getInfo();

    console.log(`Potential tropical cyclones detected: ${uniqueCount}`);

    // 5. Validation & Final Answer
    if (uniqueCount === null || uniqueCount === undefined || uniqueCount < 0) {
      console.log("<answer>C3</answer>");
    } else if (uniqueCount >= 3) {
      console.log("<answer>A</answer>");
    } else {
      console.log("<answer>B</answer>");
    }

  } catch (error) {
    console.error(`Error: ${error.message}`);
    console.log("<answer>D</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
